  "carter/hub/0": { id: "siege.voice.carter.hub_0", text: "Ask what you like. If I don't know, I'll say. If I do know and I'm frightened to say it, I'll say that too.", seconds: 6.4 },
  "carter/hub/1": { id: "siege.voice.carter.hub_1", text: "You came back. People from the bright side mostly don't. Ask.", seconds: 4.6 },
