  "carter/named/0": { id: "siege.voice.carter.named_0", text: "The Court's quiet. You can hear the river now. I never knew it made a noise.", seconds: 3.54 },
  "carter/named/1": { id: "siege.voice.carter.named_1", text: "Say it again. My name. I like hearing it.", seconds: 1.91 },
  "carter/named/2": { id: "siege.voice.carter.named_2", text: "The rail's quiet. I keep waking at dawn anyway.", seconds: 2.37 },
  "carter/named/3": { id: "siege.voice.carter.named_3", text: "He sleeps a lot, my brother. Smiles in it. No sound.", seconds: 2.87 },
  "corvin/hub/0": { id: "siege.voice.corvin.hub_0", text: "Ask. Quickly. Every word I say to you is a word I'm not singing, and they notice.", seconds: 6.1 },
  "corvin/hub/1": { id: "siege.voice.corvin.hub_1", text: "Stand still. The water carries better when you stand still.", seconds: 4.5 },
