  "corvin/hub/3": { id: "siege.voice.corvin.hub_3", text: "Speak low. I am borrowing this breath from a tune and it will be wanted back.", seconds: 5.9 },
  "elias/hub/0": { id: "siege.voice.elias.hub_0", text: "Mind the lamp. Have you read them? Any of them? I'd like to know someone has.", seconds: 5.9 },
  "elias/hub/1": { id: "siege.voice.elias.hub_1", text: "Is that the tide or is that you? Come up, come up.", seconds: 4.4 },
  "elias/hub/2": { id: "siege.voice.elias.hub_2", text: "Careful on the stair. It has one more step than it used to.", seconds: 4.7 },
  "elias/hub/3": { id: "siege.voice.elias.hub_3", text: "I was just writing to her. It will keep. What can I tell you?", seconds: 4.7 },
