  "hesper/hub/1": { id: "siege.voice.hesper.hub_1", text: "You're back. Good. I've kept the tea warm, I don't know why.", seconds: 3.09 },
  "hesper/hub/2": { id: "siege.voice.hesper.hub_2", text: "He's out with the reeds. He's always out with the reeds now.", seconds: 2.79 },
  "hesper/hub/3": { id: "siege.voice.hesper.hub_3", text: "Tell me what you saw. Take your time. I've nothing but time.", seconds: 2.83 },
