  "kesh/hub/0": { id: "siege.voice.kesh.hub_0", text: "Something you wanted?", seconds: 0.74 },
  "kesh/hub/1": { id: "siege.voice.kesh.hub_1", text: "Back again. The view hasn't changed.", seconds: 2.42 },
  "kesh/hub/2": { id: "siege.voice.kesh.hub_2", text: "You're the one who reads the wall. Hello.", seconds: 2.37 },
  "kesh/hub/3": { id: "siege.voice.kesh.hub_3", text: "Mind the edge. I said that last time too.", seconds: 2.97 },
  "kesh/spanwait/0": { id: "siege.voice.kesh.spanwait_0", text: "Cadet. You haven't crossed yet.", seconds: 1.77 },
  "kesh/spanwait/1": { id: "siege.voice.kesh.spanwait_1", text: "Still on this side of the gorge, I see. The Span hasn't moved.", seconds: 3.62 },
  "kesh/spanwait/2": { id: "siege.voice.kesh.spanwait_2", text: "The wind's from the east today. Lean left.", seconds: 3.05 },
  "kesh/spanwait/3": { id: "siege.voice.kesh.spanwait_3", text: "You're welcome to stand here. The Span isn't going to cross itself.", seconds: 3.41 },
  "kesh/sworn/0": { id: "siege.voice.kesh.sworn_0", text: "Rider. What do you need?", seconds: 1.46 },
