  "nell/hub/2": { id: "siege.voice.nell.hub_2", text: "The plank held. It's fond of you.", seconds: 1.69 },
  "nell/hub/3": { id: "siege.voice.nell.hub_3", text: "You again. Good. I was running out of people to talk to who aren't eels.", seconds: 3.55 },
  "nell/motherwait/0": { id: "siege.voice.nell.motherwait_0", text: "Goody Sedge has had her look. Now the fen wants one thing done.", seconds: 3.22 },
