  "nell/sworn/1": { id: "siege.voice.nell.sworn_1", text: "Witch. Sit, the kettle's on. It's always on.", seconds: 2.0 },
  "nell/sworn/2": { id: "siege.voice.nell.sworn_2", text: "You've got that look. The fen's been talking to you. Tell me.", seconds: 2.95 },
  "nell/sworn/3": { id: "siege.voice.nell.sworn_3", text: "Mind the plank. Oh, you did. Good.", seconds: 1.9 },
  "nessa/hub/0": { id: "siege.voice.nessa.hub_0", text: "Well? Have you watched him?", seconds: 1.24 },
