  "nessa/hub/3": { id: "siege.voice.nessa.hub_3", text: "I've been counting how long he stands at the back door. Ask me how long.", seconds: 4.2 },
  "ottilie/articleswait/0": { id: "siege.voice.ottilie.articleswait_0", text: "Thirty-two Regals for your share. I'll take it when you have it on you.", seconds: 3.32 },
