  "ottilie/articleswait/2": { id: "siege.voice.ottilie.articleswait_2", text: "Your line in the book is still blank. It's waiting.", seconds: 2.29 },
  "ottilie/articleswait/3": { id: "siege.voice.ottilie.articleswait_3", text: "Debt doesn't go away for being ignored. I'd know.", seconds: 2.84 },
  "ottilie/bridewait/0": { id: "siege.voice.ottilie.bridewait_0", text: "You have a crew. Now take them to the sunken chapel. The Bride is waiting.", seconds: 3.86 },
  "ottilie/bridewait/1": { id: "siege.voice.ottilie.bridewait_1", text: "Three hands. It's a crew if you say it loudly enough.", seconds: 2.55 },
  "ottilie/bridewait/2": { id: "siege.voice.ottilie.bridewait_2", text: "The chapel tower shows above the water when the moon's dark. That's your night.", seconds: 3.58 },
  "ottilie/bridewait/3": { id: "siege.voice.ottilie.bridewait_3", text: "She's still waiting. Somebody ought to stop her.", seconds: 2.29 },
  "ottilie/crewwait/0": { id: "siege.voice.ottilie.crewwait_0", text: "You're in the book. Now raise a crew: three guards sworn to your keep, and tell me when you have them.", seconds: 5.0 },
  "ottilie/crewwait/1": { id: "siege.voice.ottilie.crewwait_1", text: "No crew yet? A captain alone is a passenger with opinions.", seconds: 3.36 },
  "ottilie/crewwait/2": { id: "siege.voice.ottilie.crewwait_2", text: "Three hands, sworn to your keep. Then come and tell me.", seconds: 2.88 },
  "ottilie/crewwait/3": { id: "siege.voice.ottilie.crewwait_3", text: "You'll want ones who can swim. Not everyone thinks to ask.", seconds: 2.7 },
  "ottilie/hub/0": { id: "siege.voice.ottilie.hub_0", text: "What can I do for you?", seconds: 0.87 },
  "ottilie/hub/1": { id: "siege.voice.ottilie.hub_1", text: "Back. Still not in the book.", seconds: 1.3 },
  "ottilie/hub/2": { id: "siege.voice.ottilie.hub_2", text: "The tide's on the turn. You've got a minute.", seconds: 1.88 },
  "ottilie/hub/3": { id: "siege.voice.ottilie.hub_3", text: "Ink, rope or gossip? I've got all three.", seconds: 2.21 },
  "ottilie/sworn/0": { id: "siege.voice.ottilie.sworn_0", text: "What do you need, Captain?", seconds: 0.95 },
  "ottilie/sworn/1": { id: "siege.voice.ottilie.sworn_1", text: "Captain. Your share's paid up this season. Mine isn't. Don't tell anyone.", seconds: 3.77 },
  "ottilie/sworn/2": { id: "siege.voice.ottilie.sworn_2", text: "Your crew drink in the Gull. They speak well of you. Mostly.", seconds: 2.8 },
  "ottilie/sworn/3": { id: "siege.voice.ottilie.sworn_3", text: "The book's open. It's always open. Sit.", seconds: 2.39 },
  "sage/hub/0": { id: "siege.voice.sage.hub_0", text: "Catalogue's up to date. What are we puzzling over?", seconds: 3.09 },
  "sage/hub/1": { id: "siege.voice.sage.hub_1", text: "Don't move that pile, it's in an order. What have you found?", seconds: 3.03 },
  "sage/hub/2": { id: "siege.voice.sage.hub_2", text: "Oh, it's you! I was hoping it was you and not a draught.", seconds: 3.02 },
  "sage/hub/3": { id: "siege.voice.sage.hub_3", text: "Ink's wet, mind your sleeve. Go on, what's the question?", seconds: 3.15 },
  "sigrun/hub/0": { id: "siege.voice.sigrun.hub_0", text: "Door. Shut. What is it?", seconds: 1.55 },
  "sigrun/hub/1": { id: "siege.voice.sigrun.hub_1", text: "You'll want feeding. Southerners always do. Talk first.", seconds: 3.23 },
  "sigrun/hub/2": { id: "siege.voice.sigrun.hub_2", text: "Boots off or stay by the door. What now?", seconds: 2.05 },
  "sigrun/hub/3": { id: "siege.voice.sigrun.hub_3", text: "Lake's still there, if that's what you came to check.", seconds: 2.39 },
  "tilly/hub/0": { id: "siege.voice.tilly.hub_0", text: "Have you thought?", seconds: 0.82 },
  "tilly/hub/1": { id: "siege.voice.tilly.hub_1", text: "I saved you a place on the wall. It's the dry bit.", seconds: 2.65 },
  "tilly/hub/2": { id: "siege.voice.tilly.hub_2", text: "He's down there again. Look. Right on the line.", seconds: 2.6 },
  "tilly/hub/3": { id: "siege.voice.tilly.hub_3", text: "Did you decide? You don't have to say. I can tell if you've decided.", seconds: 3.74 },
  "ulla/haulwait/0": { id: "siege.voice.ulla.haulwait_0", text: "Sixteen iron ingots and sixteen coal. I'll take them when you have them on you.", seconds: 8.2 },
  "ulla/haulwait/1": { id: "siege.voice.ulla.haulwait_1", text: "Iron? Coal? No? Then why are you letting the cold in?", seconds: 6.5 },
  "ulla/haulwait/2": { id: "siege.voice.ulla.haulwait_2", text: "Sixteen and sixteen. I'm not going to forget the number.", seconds: 6.7 },
  "ulla/haulwait/3": { id: "siege.voice.ulla.haulwait_3", text: "She's sulking. She knows the side-hearth's waiting.", seconds: 4.1 },
