  "ulla/hub/3": { id: "siege.voice.ulla.hub_3", text: "She's in a good mood today. Must be the coal.", seconds: 3.38 },
  "ulla/huntwait/0": { id: "siege.voice.ulla.huntwait_0", text: "He's up. Now he has to go back down.", seconds: 3.5 },
  "ulla/huntwait/1": { id: "siege.voice.ulla.huntwait_1", text: "You rang it. I felt the lake take the note, all the way up here.", seconds: 5.9 },
  "ulla/huntwait/2": { id: "siege.voice.ulla.huntwait_2", text: "He's up, then. Go and put him down.", seconds: 3.37 },
  "ulla/huntwait/3": { id: "siege.voice.ulla.huntwait_3", text: "There's frost on you. Lake frost. You've been close.", seconds: 4.6 },
  "ulla/ringwait/0": { id: "siege.voice.ulla.ringwait_0", text: "That's Hroda's hand-bell pattern. First one poured in thirty years, and it came out sweet.\n\nTake it to the lake at Rimehold. Set it down on the ice at night and ring it. Something out there still answers bells.", seconds: 15.5 },
  "ulla/ringwait/1": { id: "siege.voice.ulla.ringwait_1", text: "You've still got the bell. I can hear it in your pack, humming.", seconds: 5.2 },
  "ulla/ringwait/2": { id: "siege.voice.ulla.ringwait_2", text: "The lake. At night. On the ice. I said all three.", seconds: 4.6 },
  "ulla/ringwait/3": { id: "siege.voice.ulla.ringwait_3", text: "Don't ring it in here. She'll never forgive either of us.", seconds: 4.9 },
  "ulla/sworn/0": { id: "siege.voice.ulla.sworn_0", text: "What do you need?", seconds: 1.52 },
  "ulla/sworn/1": { id: "siege.voice.ulla.sworn_1", text: "Smith. Shut the door. Good. You're learning.", seconds: 3.59 },
  "ulla/sworn/2": { id: "siege.voice.ulla.sworn_2", text: "She brightened when you came in. Don't let it go to your head.", seconds: 4.9 },
  "ulla/sworn/3": { id: "siege.voice.ulla.sworn_3", text: "Your hands have changed. They hold a hammer like it belongs to them now.", seconds: 7.1 },
  "wren/hub/0": { id: "siege.voice.wren.hub_0", text: "Still dark, still here. What do you need?", seconds: 2.61 },
  "wren/hub/1": { id: "siege.voice.wren.hub_1", text: "You again. Good. Wipe your feet, somebody has to pretend it's morning.", seconds: 4.8 },
  "wren/hub/2": { id: "siege.voice.wren.hub_2", text: "Hold this. No, the other end. Now. What is it?", seconds: 3.11 },
  "wren/hub/3": { id: "siege.voice.wren.hub_3", text: "I've a pot on and a boy with a fever. Talk while I work.", seconds: 3.84 },
